INSERT INTO dev_exam_questions (id, category_id, difficulty, question_en, question_ar, question_nl, question_fr, explanation_en, explanation_ar, explanation_nl, explanation_fr, is_active, created_at) VALUES
  (1, 1, 'BEGINNER', 'What does REST stand for?', 'ماذا تعني REST اختصاراً؟', 'Waar staat REST voor?', 'Que signifie l''acronyme REST?', 'REST stands for Representational State Transfer, an architectural style for distributed hypermedia systems.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (2, 1, 'BEGINNER', 'Which HTTP method retrieves data without modifying the resource?', 'أي طريقة HTTP تسترجع البيانات دون تعديل المورد؟', 'Welke HTTP-methode haalt gegevens op zonder de resource te wijzigen?', 'Quelle méthode HTTP récupère des données sans modifier la ressource?', 'GET is the safe and idempotent method for reading resources.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (3, 1, 'BEGINNER', 'What HTTP status code indicates a successful response (OK)?', 'ما رمز حالة HTTP الذي يشير إلى الاستجابة الناجحة (OK)؟', 'Welke HTTP-statuscode duidt op een succesvolle respons (OK)?', 'Quel code de statut HTTP indique une réponse réussie (OK)?', '200 OK is the standard success response for GET, PUT, and PATCH requests.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (4, 1, 'INTERMEDIATE', 'What makes an HTTP method "idempotent"?', 'ما الذي يجعل طريقة HTTP "idempotent"؟', 'Wat maakt een HTTP-methode "idempotent"?', 'Qu''est-ce qui rend une méthode HTTP "idempotente"?', 'An idempotent method can be called multiple times with the same effect as a single call.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (5, 1, 'INTERMEDIATE', 'Which HTTP method is NOT idempotent by definition?', 'أي طريقة HTTP ليست idempotent بطبيعتها؟', 'Welke HTTP-methode is van nature niet idempotent?', 'Quelle méthode HTTP n''est pas idempotente par définition?', 'POST creates a new resource each time it is called, so multiple calls produce different results.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (6, 1, 'INTERMEDIATE', 'What is the purpose of the HTTP Content-Type header?', 'ما الغرض من رأس HTTP Content-Type؟', 'Wat is het doel van de HTTP Content-Type header?', 'Quel est le rôle du header HTTP Content-Type?', 'Content-Type tells the receiver the media type of the request or response body.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (7, 1, 'ADVANCED', 'What is HATEOAS in REST architecture?', 'ما هو HATEOAS في معمارية REST؟', 'Wat is HATEOAS in REST-architectuur?', 'Qu''est-ce que HATEOAS dans l''architecture REST?', 'HATEOAS (Hypermedia as the Engine of Application State) means responses include links to available next actions.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (8, 1, 'ADVANCED', 'What is the meaning of HTTP status code 429?', 'ماذا يشير رمز حالة HTTP 429؟', 'Wat betekent HTTP-statuscode 429?', 'Que signifie le code de statut HTTP 429?', '429 Too Many Requests indicates the client has exceeded the server''s rate limit.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (9, 1, 'ADVANCED', 'Which HTTP method should be used for a partial update to a resource?', 'أي طريقة HTTP يجب استخدامها للتحديثات الجزئية للمورد؟', 'Welke HTTP-methode dient gebruikt te worden voor gedeeltelijke updates?', 'Quelle méthode HTTP faut-il utiliser pour une mise à jour partielle d''une ressource?', 'PATCH is designed for partial updates, while PUT replaces the entire resource.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (10, 2, 'BEGINNER', 'What does SQL stand for?', 'ماذا تعني SQL اختصاراً؟', 'Waar staat SQL voor?', 'Que signifie l''acronyme SQL?', 'SQL stands for Structured Query Language, used to manage and query relational databases.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (11, 2, 'BEGINNER', 'Which SQL command is used to retrieve data from a table?', 'أي أمر SQL يُستخدم لاسترداد البيانات من جدول؟', 'Welk SQL-commando wordt gebruikt om gegevens uit een tabel op te halen?', 'Quelle commande SQL est utilisée pour récupérer des données d''une table?', 'SELECT retrieves rows from one or more tables based on a query.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (12, 2, 'BEGINNER', 'What is a primary key in a database?', 'ما هو المفتاح الأساسي في قاعدة البيانات؟', 'Wat is een primaire sleutel in een database?', 'Qu''est-ce qu''une clé primaire dans une base de données?', 'A primary key is a column (or columns) that uniquely identifies each row in a table.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (13, 2, 'INTERMEDIATE', 'What is the N+1 query problem in ORM?', 'ما هي مشكلة استعلامات N+1 في إطار ORM؟', 'Wat is het N+1 query probleem in ORM?', 'Qu''est-ce que le problème de requêtes N+1 dans un ORM?', 'N+1 occurs when one query loads a list of entities and then one extra query fires per entity to load its relations.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (14, 2, 'INTERMEDIATE', 'What does INNER JOIN return in SQL?', 'ماذا يُعيد INNER JOIN في SQL؟', 'Wat retourneert INNER JOIN in SQL?', 'Que retourne INNER JOIN en SQL?', 'INNER JOIN returns only the rows where there is a match in both joined tables.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (15, 2, 'INTERMEDIATE', 'What is the primary purpose of database indexing?', 'ما الغرض الأساسي من الفهرسة في قاعدة البيانات؟', 'Wat is het primaire doel van database-indexering?', 'Quel est l''objectif principal de l''indexation d''une base de données?', 'Indexes speed up data retrieval by allowing the database to find rows without full table scans.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (16, 2, 'ADVANCED', 'What is database connection pooling?', 'ما هو توحيد اتصالات قاعدة البيانات (Connection Pooling)؟', 'Wat is database connection pooling?', 'Qu''est-ce que le pooling de connexions de base de données?', 'Connection pooling maintains a pool of open database connections that are reused, reducing overhead.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (17, 2, 'ADVANCED', 'What is optimistic locking in a database?', 'ما هو القفل المتفائل (Optimistic Locking) في قاعدة البيانات؟', 'Wat is optimistic locking in een database?', 'Qu''est-ce que le verrouillage optimiste dans une base de données?', 'Optimistic locking assumes no conflict and checks for concurrent modification only at commit time.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (18, 2, 'ADVANCED', 'What does the CAP theorem state about distributed databases?', 'ماذا تقول نظرية CAP عن قواعد البيانات الموزعة؟', 'Wat stelt het CAP-theorema over gedistribueerde databases?', 'Que dit le théorème CAP sur les bases de données distribuées?', 'CAP: a distributed system cannot simultaneously guarantee Consistency, Availability, and Partition tolerance.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (19, 3, 'BEGINNER', 'What does JWT stand for?', 'ماذا تعني JWT اختصاراً؟', 'Waar staat JWT voor?', 'Que signifie l''acronyme JWT?', 'JWT stands for JSON Web Token, a compact, self-contained way to transmit claims between parties.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (20, 3, 'BEGINNER', 'What are the three parts of a JWT?', 'ما هي الأجزاء الثلاثة لـ JWT؟', 'Wat zijn de drie onderdelen van een JWT?', 'Quelles sont les trois parties d''un JWT?', 'A JWT consists of a Header, Payload, and Signature, each Base64Url-encoded and separated by dots.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (21, 3, 'BEGINNER', 'Why should passwords be hashed before storage?', 'لماذا يجب تجزئة كلمات المرور قبل التخزين؟', 'Waarom moeten wachtwoorden worden gehasht voor opslag?', 'Pourquoi les mots de passe doivent-ils être hachés avant stockage?', 'Hashing is one-way and prevents passwords from being recovered if the database is compromised.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (22, 3, 'INTERMEDIATE', 'What is the difference between authentication and authorization?', 'ما الفرق بين المصادقة (authentication) والتفويض (authorization)؟', 'Wat is het verschil tussen authenticatie en autorisatie?', 'Quelle est la différence entre authentification et autorisation?', 'Authentication verifies who you are; authorization determines what you are allowed to do.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (23, 3, 'INTERMEDIATE', 'What is the primary purpose of OAuth 2.0?', 'ما الغرض الأساسي من OAuth 2.0؟', 'Wat is het primaire doel van OAuth 2.0?', 'Quel est l''objectif principal d''OAuth 2.0?', 'OAuth 2.0 allows a user to grant a third-party application limited access to their resources without sharing credentials.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (24, 3, 'INTERMEDIATE', 'What is a refresh token in OAuth 2.0?', 'ما هو رمز التحديث (Refresh Token) في OAuth 2.0؟', 'Wat is een refresh token in OAuth 2.0?', 'Qu''est-ce qu''un refresh token dans OAuth 2.0?', 'A refresh token is a long-lived credential used to obtain new short-lived access tokens without re-authentication.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (25, 3, 'ADVANCED', 'What does PKCE add to the OAuth 2.0 authorization code flow?', 'ما الذي يُضيفه PKCE إلى تدفق رمز التفويض في OAuth 2.0؟', 'Wat voegt PKCE toe aan de OAuth 2.0-autorisatiecodeflo?', 'Que PKCE ajoute-t-il au flux de code d''autorisation OAuth 2.0?', 'PKCE (Proof Key for Code Exchange) prevents authorization code interception attacks by using a code verifier and challenge.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (26, 3, 'ADVANCED', 'What is the purpose of the nonce claim in OpenID Connect?', 'ما الغرض من مطالبة nonce في OpenID Connect؟', 'Wat is het doel van de nonce-claim in OpenID Connect?', 'Quel est le rôle du claim "nonce" dans OpenID Connect?', 'The nonce is a random value included in the authentication request and verified in the ID token to prevent replay attacks.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (27, 3, 'ADVANCED', 'What characterizes multi-factor authentication (MFA)?', 'ما الذي يُميز المصادقة متعددة العوامل (MFA)؟', 'Wat kenmerkt multi-factor authenticatie (MFA)?', 'Qu''est-ce qui caractérise l''authentification multi-facteurs (MFA)?', 'MFA requires two or more independent verification factors from different categories: something you know, have, or are.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (28, 4, 'BEGINNER', 'What is Role-Based Access Control (RBAC)?', NULL, NULL, NULL, 'RBAC assigns permissions to users based on their roles, simplifying permission management.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (29, 4, 'BEGINNER', 'What does ACL stand for in access control?', NULL, NULL, NULL, 'ACL stands for Access Control List, a list that specifies which subjects can perform which actions on a resource.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (30, 4, 'BEGINNER', 'What does a permission define in an access control system?', NULL, NULL, NULL, 'A permission defines what actions (read, write, delete) a subject is allowed to perform on a resource.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (31, 4, 'INTERMEDIATE', 'What is the principle of least privilege?', NULL, NULL, NULL, 'Grant subjects only the minimum permissions they need to perform their assigned tasks.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (32, 4, 'INTERMEDIATE', 'What is Attribute-Based Access Control (ABAC)?', NULL, NULL, NULL, 'ABAC makes access decisions based on attributes of the user, resource, and environment.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (33, 4, 'INTERMEDIATE', 'What is a security policy in ABAC?', NULL, NULL, NULL, 'A policy defines the rules that combine attributes to determine whether access should be granted.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (34, 4, 'ADVANCED', 'What is claims-based authorization?', NULL, NULL, NULL, 'Claims-based authorization uses named values in a security token (claims) to make access decisions.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (35, 4, 'ADVANCED', 'What is a Policy Decision Point (PDP)?', NULL, NULL, NULL, 'A PDP is the component responsible for evaluating access control policies and granting or denying access.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (36, 4, 'ADVANCED', 'What is permission delegation?', NULL, NULL, NULL, 'Delegation allows a user to temporarily grant their permissions to another entity to act on their behalf.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (37, 5, 'BEGINNER', 'What is the Virtual DOM?', NULL, NULL, NULL, 'The Virtual DOM is an in-memory copy of the real DOM; frameworks diff it to compute minimal real DOM updates.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (38, 5, 'BEGINNER', 'What is component-based architecture in frontend development?', NULL, NULL, NULL, 'UI is built from independent, reusable components that encapsulate their own state and presentation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (39, 5, 'BEGINNER', 'What is a Single Page Application (SPA)?', NULL, NULL, NULL, 'An SPA loads a single HTML document and dynamically updates content without full page reloads.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (40, 5, 'INTERMEDIATE', 'What is hydration in server-side rendered frontend frameworks?', NULL, NULL, NULL, 'Hydration attaches JavaScript event handlers to server-rendered HTML so the page becomes interactive.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (41, 5, 'INTERMEDIATE', 'What is lazy loading in frontend development?', NULL, NULL, NULL, 'Lazy loading defers loading resources until they are needed, reducing initial bundle size.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (42, 5, 'INTERMEDIATE', 'What is the purpose of CSS-in-JS?', NULL, NULL, NULL, 'CSS-in-JS allows writing component-scoped styles in JavaScript, enabling dynamic styling.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (43, 5, 'ADVANCED', 'What is code splitting in web applications?', NULL, NULL, NULL, 'Code splitting divides the JavaScript bundle into smaller chunks loaded on demand, improving Time to Interactive.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (44, 5, 'ADVANCED', 'What is the purpose of a service worker?', NULL, NULL, NULL, 'Service workers run in the background enabling offline support, caching strategies, and background sync.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (45, 5, 'ADVANCED', 'What is tree shaking in JavaScript bundlers?', NULL, NULL, NULL, 'Tree shaking removes dead (unused) code from the final bundle at build time, reducing its size.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (46, 6, 'BEGINNER', 'What is the service layer in backend architecture?', NULL, NULL, NULL, 'The service layer encapsulates business logic, separating it from controllers and data access.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (47, 6, 'BEGINNER', 'What is dependency injection?', NULL, NULL, NULL, 'Dependency injection provides a class''s dependencies from outside rather than letting it create them.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (48, 6, 'BEGINNER', 'What is a DTO (Data Transfer Object)?', NULL, NULL, NULL, 'A DTO is a simple object carrying data between layers or over the network, containing no business logic.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (49, 6, 'INTERMEDIATE', 'What is the repository pattern?', NULL, NULL, NULL, 'The repository pattern abstracts data persistence behind an interface, decoupling business logic from storage.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (50, 6, 'INTERMEDIATE', 'What characterizes a pure function?', NULL, NULL, NULL, 'A pure function always returns the same output for the same inputs and produces no side effects.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (51, 6, 'INTERMEDIATE', 'What is the purpose of the Builder design pattern?', NULL, NULL, NULL, 'Builder constructs complex objects step by step using a fluent API, separating construction from representation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (52, 6, 'ADVANCED', 'What is CQRS (Command Query Responsibility Segregation)?', NULL, NULL, NULL, 'CQRS separates the read model (queries) from the write model (commands) for independent scaling and optimization.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (53, 6, 'ADVANCED', 'What is Event Sourcing?', NULL, NULL, NULL, 'Event Sourcing stores state as an immutable sequence of events; current state is derived by replaying events.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (54, 6, 'ADVANCED', 'What is the Saga pattern in microservices?', NULL, NULL, NULL, 'A Saga is a sequence of local transactions, each publishing events that trigger the next step, managing long-running processes.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (55, 7, 'BEGINNER', 'What is input validation?', NULL, NULL, NULL, 'Input validation verifies that user-supplied data meets expected format, type, and constraint requirements.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (56, 7, 'BEGINNER', 'What does the @NotNull annotation do in Java Bean Validation?', NULL, NULL, NULL, '@NotNull ensures the annotated element value is not null; validation fails if null is provided.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (57, 7, 'BEGINNER', 'What is client-side validation?', NULL, NULL, NULL, 'Client-side validation checks input in the browser before submission, improving UX but not replacing server validation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (58, 7, 'INTERMEDIATE', 'What is the difference between whitelist and blacklist validation?', NULL, NULL, NULL, 'Whitelist (allowlist) accepts only known-good values; blacklist (denylist) rejects known-bad values.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (59, 7, 'INTERMEDIATE', 'What is cross-field validation?', NULL, NULL, NULL, 'Cross-field validation checks relationships between multiple fields in the same object.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (60, 7, 'INTERMEDIATE', 'What should always accompany client-side validation?', NULL, NULL, NULL, 'Server-side validation must always be performed independently, as client-side can be bypassed.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (61, 7, 'ADVANCED', 'What is the Java Bean Validation (JSR 380) specification?', NULL, NULL, NULL, 'Bean Validation is a Java standard for declaring validation constraints on objects via annotations.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (62, 7, 'ADVANCED', 'What is a custom constraint in Java Bean Validation?', NULL, NULL, NULL, 'A custom constraint is a user-defined annotation paired with a ConstraintValidator implementation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (63, 7, 'ADVANCED', 'What is the purpose of validation groups in Bean Validation?', NULL, NULL, NULL, 'Validation groups allow different subsets of constraints to be applied in different contexts.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (64, 8, 'BEGINNER', 'What is SQL Injection?', NULL, NULL, NULL, 'SQL Injection inserts malicious SQL through input fields to manipulate or expose database data.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (65, 8, 'BEGINNER', 'What is Cross-Site Scripting (XSS)?', NULL, NULL, NULL, 'XSS injects malicious scripts into web pages that execute in other users'' browsers.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (66, 8, 'BEGINNER', 'What does HTTPS provide over HTTP?', NULL, NULL, NULL, 'HTTPS adds TLS/SSL encryption, ensuring data in transit is confidential and tamper-proof.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (67, 8, 'INTERMEDIATE', 'What is a CSRF attack?', NULL, NULL, NULL, 'CSRF tricks a logged-in user''s browser into sending forged requests to a trusted site.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (68, 8, 'INTERMEDIATE', 'What is the purpose of the Content-Security-Policy response header?', NULL, NULL, NULL, 'CSP instructs the browser which content sources are trusted, preventing XSS and injection attacks.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (69, 8, 'INTERMEDIATE', 'What is a parameterized query (prepared statement)?', NULL, NULL, NULL, 'Parameterized queries separate SQL code from data, eliminating SQL injection by treating input as data only.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (70, 8, 'ADVANCED', 'What is the OWASP Top 10?', NULL, NULL, NULL, 'The OWASP Top 10 is a community-driven list of the ten most critical web application security risks.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (71, 8, 'ADVANCED', 'What is penetration testing?', NULL, NULL, NULL, 'Penetration testing is an authorized simulated attack on a system to identify exploitable security vulnerabilities.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (72, 8, 'ADVANCED', 'What is a dependency vulnerability scan?', NULL, NULL, NULL, 'It checks third-party libraries used by the application for publicly disclosed security vulnerabilities.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (73, 9, 'BEGINNER', 'What is a unit test?', NULL, NULL, NULL, 'A unit test verifies the behavior of a single isolated unit of code, such as a method or class.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (74, 9, 'BEGINNER', 'What is a test mock?', NULL, NULL, NULL, 'A mock is a simulated replacement for a real dependency that lets you isolate and verify interactions.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (75, 9, 'BEGINNER', 'What is the difference between a stub and a mock?', NULL, NULL, NULL, 'Stubs provide canned responses for indirect inputs; mocks also verify expected interactions were made.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (76, 9, 'INTERMEDIATE', 'What is Test-Driven Development (TDD)?', NULL, NULL, NULL, 'TDD writes a failing test first, then minimal code to pass it, then refactors while keeping tests green.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (77, 9, 'INTERMEDIATE', 'What is test coverage?', NULL, NULL, NULL, 'Test coverage measures the percentage of production code lines or branches executed during the test suite.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (78, 9, 'INTERMEDIATE', 'What is an integration test?', NULL, NULL, NULL, 'Integration tests verify multiple components or layers work correctly together, often with real infrastructure.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (79, 9, 'ADVANCED', 'What is contract testing?', NULL, NULL, NULL, 'Contract testing verifies that an API consumer and provider agree on the interface, detecting breaking changes.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (80, 9, 'ADVANCED', 'What is mutation testing?', NULL, NULL, NULL, 'Mutation testing introduces small code changes to verify the test suite detects and fails on them.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (81, 9, 'ADVANCED', 'What is a test fixture?', NULL, NULL, NULL, 'A test fixture is the fixed state of objects and data used as a known baseline for running tests.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (82, 10, 'BEGINNER', 'What is an exception in programming?', NULL, NULL, NULL, 'An exception is an event that disrupts the normal execution flow of a program.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (83, 10, 'BEGINNER', 'What is the purpose of a try-catch block?', NULL, NULL, NULL, 'A try-catch block handles exceptions gracefully, preventing uncontrolled application crashes.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (84, 10, 'BEGINNER', 'What is the difference between checked and unchecked exceptions in Java?', NULL, NULL, NULL, 'Checked exceptions must be declared or handled; unchecked (runtime) exceptions do not require explicit handling.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (85, 10, 'INTERMEDIATE', 'Which HTTP status code range indicates server-side errors?', NULL, NULL, NULL, '5xx codes (e.g., 500 Internal Server Error) indicate the server failed to fulfil a valid request.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (86, 10, 'INTERMEDIATE', 'What is a global exception handler in Spring Boot?', NULL, NULL, NULL, '@ControllerAdvice (with @ExceptionHandler methods) intercepts and handles exceptions across all controllers centrally.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (87, 10, 'INTERMEDIATE', 'What is the purpose of returning a Problem Details response (RFC 7807)?', NULL, NULL, NULL, 'Problem Details provides a standardized, machine-readable error format for HTTP API responses.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (88, 10, 'ADVANCED', 'What is the circuit breaker pattern?', NULL, NULL, NULL, 'A circuit breaker stops calls to a failing service after a threshold, preventing cascading failures.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (89, 10, 'ADVANCED', 'What is graceful degradation?', NULL, NULL, NULL, 'Graceful degradation maintains partial functionality when some system components fail.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (90, 10, 'ADVANCED', 'What is a dead letter queue (DLQ)?', NULL, NULL, NULL, 'A DLQ holds messages that could not be processed so they can be analysed and reprocessed.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (91, 11, 'BEGINNER', 'What is caching?', NULL, NULL, NULL, 'Caching stores frequently accessed data temporarily so future requests are served faster.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (92, 11, 'BEGINNER', 'What does "response time" measure?', NULL, NULL, NULL, 'Response time is the total duration from when a request is sent until the full response is received.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (93, 11, 'BEGINNER', 'What is a performance bottleneck?', NULL, NULL, NULL, 'A bottleneck is the component limiting overall system throughput.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (94, 11, 'INTERMEDIATE', 'What is a CDN (Content Delivery Network)?', NULL, NULL, NULL, 'A CDN distributes content from edge servers geographically close to users, reducing latency.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (95, 11, 'INTERMEDIATE', 'What is lazy loading in the context of database queries?', NULL, NULL, NULL, 'Lazy loading fetches related entities only when first accessed, deferring unnecessary queries.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (96, 11, 'INTERMEDIATE', 'What is horizontal scaling?', NULL, NULL, NULL, 'Horizontal scaling adds more instances of a service to handle increased load.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (97, 11, 'ADVANCED', 'What is distributed caching?', NULL, NULL, NULL, 'Distributed caching (e.g., Redis) shares a cache across multiple service instances.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (98, 11, 'ADVANCED', 'What is asynchronous processing?', NULL, NULL, NULL, 'Asynchronous processing executes operations in the background without blocking the calling thread.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (99, 11, 'ADVANCED', 'What does a profiler measure in application performance?', NULL, NULL, NULL, 'A profiler identifies where an application spends CPU time and memory to guide optimisation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (100, 12, 'BEGINNER', 'What does i18n stand for?', NULL, NULL, NULL, 'i18n stands for internationalization (18 letters between the first i and the last n).', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (101, 12, 'BEGINNER', 'What is localization (l10n)?', NULL, NULL, NULL, 'Localization adapts internationalized software for a specific locale, culture, or language.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (102, 12, 'BEGINNER', 'What is a locale?', NULL, NULL, NULL, 'A locale is a combination of language and regional settings (e.g., fr-BE, en-US).', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (103, 12, 'INTERMEDIATE', 'What is RTL (Right-to-Left) language support?', NULL, NULL, NULL, 'RTL support renders text and layout from right to left for languages like Arabic and Hebrew.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (104, 12, 'INTERMEDIATE', 'What is a message key in i18n?', NULL, NULL, NULL, 'A message key is a unique identifier mapped to locale-specific translated strings.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (105, 12, 'INTERMEDIATE', 'What is pluralization in i18n?', NULL, NULL, NULL, 'Pluralization uses different translation strings for singular, plural, and other grammatical forms.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (106, 12, 'ADVANCED', 'What is the ICU message format?', NULL, NULL, NULL, 'ICU provides a standard format for locale-sensitive messages including plural rules and variable interpolation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (107, 12, 'ADVANCED', 'What HTTP header does a client use to indicate its preferred language?', NULL, NULL, NULL, 'The Accept-Language header communicates the client''s preferred languages for content negotiation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (108, 12, 'ADVANCED', 'What is a locale fallback strategy?', NULL, NULL, NULL, 'Fallback serves a default locale''s translation when no translation exists for the requested locale.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (109, 13, 'BEGINNER', 'What is Docker?', 'ما هو Docker؟', 'Wat is Docker?', 'Qu''est-ce que Docker?', 'Docker is a platform that packages applications and their dependencies into portable containers.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (110, 13, 'BEGINNER', 'What does CI/CD stand for?', 'ماذا تعني CI/CD اختصاراً؟', 'Waar staat CI/CD voor?', 'Que signifie CI/CD?', 'CI/CD stands for Continuous Integration / Continuous Delivery (or Deployment).', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (111, 13, 'BEGINNER', 'What is a Dockerfile?', 'ما هو Dockerfile؟', 'Wat is een Dockerfile?', 'Qu''est-ce qu''un Dockerfile?', 'A Dockerfile is a script containing instructions to build a Docker image.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (112, 13, 'INTERMEDIATE', 'What is the main difference between a container and a virtual machine?', 'ما الفرق الرئيسي بين الحاوية والجهاز الافتراضي؟', 'Wat is het grote verschil tussen een container en een virtuele machine?', 'Quelle est la principale différence entre un conteneur et une machine virtuelle?', 'Containers share the host OS kernel; VMs each include a full guest OS, making containers much lighter.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (113, 13, 'INTERMEDIATE', 'What does Kubernetes provide?', 'ماذا يوفر Kubernetes؟', 'Wat biedt Kubernetes?', 'Que fournit Kubernetes?', 'Kubernetes automates container deployment, scaling, self-healing, and management across clusters.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (114, 13, 'INTERMEDIATE', 'What is an application health check endpoint?', 'ما هو نقطة نهاية فحص صحة التطبيق؟', 'Wat is een health check eindpunt voor een applicatie?', 'Qu''est-ce qu''un point de terminaison health check?', 'A health check endpoint lets infrastructure verify that an application instance is running and ready.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (115, 13, 'ADVANCED', 'What is blue-green deployment?', 'ما هو نشر الأزرق-الأخضر (Blue-Green Deployment)؟', 'Wat is blue-green deployment?', 'Qu''est-ce que le déploiement blue-green?', 'Blue-green keeps two identical environments; traffic is switched to the new (green) one after verification.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (116, 13, 'ADVANCED', 'What is a canary release?', 'ما هو إصدار الكناري (Canary Release)؟', 'Wat is een canary release?', 'Qu''est-ce qu''une release canary?', 'A canary release routes a small percentage of traffic to the new version, allowing gradual validation.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (117, 13, 'ADVANCED', 'What is Infrastructure as Code (IaC)?', 'ما هي البنية التحتية كرمز (IaC)؟', 'Wat is Infrastructure as Code (IaC)?', 'Qu''est-ce que l''Infrastructure as Code (IaC)?', 'IaC manages infrastructure through version-controlled, machine-readable definition files.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (118, 14, 'BEGINNER', 'What is application logging?', NULL, NULL, NULL, 'Logging records events, messages, and errors for diagnostics, auditing, and debugging.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (119, 14, 'BEGINNER', 'What is a log level?', NULL, NULL, NULL, 'A log level is a severity classification for messages: DEBUG, INFO, WARN, ERROR, FATAL.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (120, 14, 'BEGINNER', 'What is monitoring in software systems?', NULL, NULL, NULL, 'Monitoring continuously observes system health, performance metrics, and availability.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (121, 14, 'INTERMEDIATE', 'What is structured logging?', NULL, NULL, NULL, 'Structured logging writes entries in a machine-parseable format (e.g., JSON) enabling automated analysis.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (122, 14, 'INTERMEDIATE', 'What is APM (Application Performance Monitoring)?', NULL, NULL, NULL, 'APM tracks response times, error rates, throughput, and resource usage of a live application.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (123, 14, 'INTERMEDIATE', 'What is a metric in monitoring?', NULL, NULL, NULL, 'A metric is a time-series quantitative measurement of system behaviour (e.g., requests per second).', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (124, 14, 'ADVANCED', 'What is distributed tracing?', NULL, NULL, NULL, 'Distributed tracing tracks a request''s complete journey across multiple services using a correlation ID.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (125, 14, 'ADVANCED', 'What is a Service Level Agreement (SLA)?', NULL, NULL, NULL, 'An SLA is a contractual commitment defining expected service performance and availability targets.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (126, 14, 'ADVANCED', 'What is alerting in monitoring systems?', NULL, NULL, NULL, 'Alerting automatically notifies engineers when metrics exceed defined thresholds.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (127, 15, 'BEGINNER', 'What is Continuous Integration (CI)?', NULL, NULL, NULL, 'CI automatically builds and tests code on each commit, catching integration issues early.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (128, 15, 'BEGINNER', 'What is a CI pipeline?', NULL, NULL, NULL, 'A pipeline is an automated sequence of build, test, and deploy steps triggered by code changes.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (129, 15, 'BEGINNER', 'What is the main benefit CI provides to a development team?', NULL, NULL, NULL, 'CI enables early detection of integration bugs and regressions before they reach production.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (130, 15, 'INTERMEDIATE', 'What is a deployment artifact?', NULL, NULL, NULL, 'A deployment artifact is a versioned, packaged build output (e.g., JAR, Docker image) ready to deploy.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (131, 15, 'INTERMEDIATE', 'What is a rollback in a CI/CD workflow?', NULL, NULL, NULL, 'A rollback reverts to a previous known-good version when a deployment fails.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (132, 15, 'INTERMEDIATE', 'What is Continuous Deployment?', NULL, NULL, NULL, 'Continuous Deployment automatically deploys every change that passes all pipeline tests to production.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (133, 15, 'ADVANCED', 'What is GitOps?', NULL, NULL, NULL, 'GitOps uses Git repositories as the single source of truth for both application and infrastructure configuration.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (134, 15, 'ADVANCED', 'What is a feature flag (feature toggle)?', NULL, NULL, NULL, 'A feature flag enables or disables features at runtime via configuration, without redeployment.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (135, 15, 'ADVANCED', 'What is a shift-left approach in CI/CD?', NULL, NULL, NULL, 'Shift-left moves testing, security scanning, and quality checks earlier in the development process.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (136, 16, 'BEGINNER', 'What is a multipart form data request?', NULL, NULL, NULL, 'Multipart/form-data is the HTTP encoding used for uploading files alongside form fields.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (137, 16, 'BEGINNER', 'What is a MIME type?', NULL, NULL, NULL, 'A MIME type (e.g., image/png) identifies the format of content in an HTTP message.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (138, 16, 'BEGINNER', 'Why should uploaded files be validated on the server?', NULL, NULL, NULL, 'Server-side validation ensures files meet expected type and size constraints and prevents malicious uploads.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (139, 16, 'INTERMEDIATE', 'What is streaming in file upload/download?', NULL, NULL, NULL, 'Streaming processes data in chunks without loading the entire file into memory, enabling large file handling.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (140, 16, 'INTERMEDIATE', 'What is a presigned URL for file upload?', NULL, NULL, NULL, 'A presigned URL is a temporary URL with embedded credentials allowing direct upload to object storage.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (141, 16, 'INTERMEDIATE', 'Why should servers generate unique filenames for uploads?', NULL, NULL, NULL, 'Unique server-generated filenames prevent filename collisions and path traversal attacks.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (142, 16, 'ADVANCED', 'What is resumable file upload?', NULL, NULL, NULL, 'Resumable upload allows an interrupted upload to continue from its last saved position.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (143, 16, 'ADVANCED', 'What is content-addressed storage?', NULL, NULL, NULL, 'Content-addressed storage indexes files by the hash of their content, enabling deduplication.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (144, 16, 'ADVANCED', 'What security risk must be prevented when allowing file uploads?', NULL, NULL, NULL, 'Path traversal attacks use crafted filenames to gain access to directories outside the intended upload path.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (145, 17, 'BEGINNER', 'What is data export?', NULL, NULL, NULL, 'Data export generates a downloadable file (CSV, Excel, PDF) containing application data.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (146, 17, 'BEGINNER', 'What is a CSV file?', NULL, NULL, NULL, 'A CSV (Comma-Separated Values) file stores tabular data as plain text with values separated by commas.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (147, 17, 'BEGINNER', 'What is pagination in data reporting?', NULL, NULL, NULL, 'Pagination splits large result sets into smaller pages to improve performance and usability.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (148, 17, 'INTERMEDIATE', 'What is a report template?', NULL, NULL, NULL, 'A report template is a predefined layout used to generate consistently formatted reports.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (149, 17, 'INTERMEDIATE', 'What is data aggregation in reporting?', NULL, NULL, NULL, 'Data aggregation computes summary statistics (count, sum, average) over a dataset.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (150, 17, 'INTERMEDIATE', 'What is a scheduled report?', NULL, NULL, NULL, 'A scheduled report is automatically generated and delivered at configured time intervals.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (151, 17, 'ADVANCED', 'What is an ETL process?', NULL, NULL, NULL, 'ETL (Extract, Transform, Load) extracts data from a source, transforms it, and loads it into a target system.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (152, 17, 'ADVANCED', 'What is a data warehouse?', NULL, NULL, NULL, 'A data warehouse is a centralized repository optimised for analytical queries and historical reporting.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (153, 17, 'ADVANCED', 'What is report caching?', NULL, NULL, NULL, 'Report caching stores generated report output so repeat requests are served without regeneration.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (154, 18, 'BEGINNER', 'What is a search query?', NULL, NULL, NULL, 'A search query is a request to find records matching specified criteria.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (155, 18, 'BEGINNER', 'What is a filter in data retrieval?', NULL, NULL, NULL, 'A filter is a condition that narrows down a result set to only matching records.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (156, 18, 'BEGINNER', 'What is sorting in data retrieval?', NULL, NULL, NULL, 'Sorting orders result records by one or more fields in ascending or descending order.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (157, 18, 'INTERMEDIATE', 'What is full-text search?', NULL, NULL, NULL, 'Full-text search queries the content of text fields rather than matching exact column values.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (158, 18, 'INTERMEDIATE', 'What is faceted search?', NULL, NULL, NULL, 'Faceted search lets users filter results by multiple attribute categories simultaneously.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (159, 18, 'INTERMEDIATE', 'What is offset-based pagination?', NULL, NULL, NULL, 'Offset-based pagination skips a fixed number of records to retrieve a specific page of results.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (160, 18, 'ADVANCED', 'What is an Elasticsearch index?', NULL, NULL, NULL, 'An Elasticsearch index is a collection of documents optimised for full-text search and analytics.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (161, 18, 'ADVANCED', 'What is cursor-based pagination?', NULL, NULL, NULL, 'Cursor-based pagination uses a stable pointer to track position, avoiding the shifting problem of offset pagination.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (162, 18, 'ADVANCED', 'What is relevance scoring in search engines?', NULL, NULL, NULL, 'Relevance scoring ranks search results by how closely they match the query, using algorithms like TF-IDF.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (163, 19, 'BEGINNER', 'What is an environment variable?', NULL, NULL, NULL, 'An environment variable is a named value set in the OS environment and read by the application at runtime.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (164, 19, 'BEGINNER', 'What is the purpose of application.yml in Spring Boot?', NULL, NULL, NULL, 'application.yml is the externalized configuration file for a Spring Boot application.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (165, 19, 'BEGINNER', 'What is a configuration profile?', NULL, NULL, NULL, 'A profile is a named set of configuration properties activated for a specific environment (dev, prod).', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (166, 19, 'INTERMEDIATE', 'What is configuration externalization?', NULL, NULL, NULL, 'Externalization keeps configuration values outside the deployable artifact so they can change without rebuild.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (167, 19, 'INTERMEDIATE', 'What are Spring Profiles used for?', NULL, NULL, NULL, 'Spring Profiles activate different beans and properties per environment, enabling environment-specific config.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (168, 19, 'INTERMEDIATE', 'What is a secret in application configuration?', NULL, NULL, NULL, 'A secret is a sensitive value (password, API key) that must not be stored in plain text or version control.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (169, 19, 'ADVANCED', 'What is a config server in microservices?', NULL, NULL, NULL, 'A config server provides centralised, dynamic configuration to all services in a microservices architecture.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (170, 19, 'ADVANCED', 'What does the 12-Factor App principle say about configuration?', NULL, NULL, NULL, 'Factor III: store config in the environment, not in the codebase, so it can vary between deployments.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000'),
  (171, 19, 'ADVANCED', 'What is a feature flag in configuration?', NULL, NULL, NULL, 'A feature flag is a configuration toggle that enables or disables features without redeployment.', NULL, NULL, NULL, TRUE, '2026-05-21 08:50:39.000000');
