  (13, 4, 1, TRUE, 'Calling it multiple times produces the same result as one call', 'استدعاؤه عدة مرات يعطي نفس نتيجة استدعائه مرة واحدة', 'Meerdere aanroepen geven hetzelfde resultaat als één aanroep', 'L''appeler plusieurs fois produit le même résultat qu''une seule fois'),
  (14, 4, 2, FALSE, 'It does not require authentication', 'لا يتطلب مصادقة', 'Het vereist geen authenticatie', 'Il ne nécessite pas d''authentification'),
