  (21, 6, 1, TRUE, 'Specifies the media type of the request or response body', 'يحدد نوع الوسائط لجسم الطلب أو الاستجابة', 'Specificeert het mediatype van de aanvraag- of antwoordbody', 'Spécifie le type de média du corps de la requête ou réponse'),
  (22, 6, 2, FALSE, 'Sets the character encoding of the URL', 'يضبط ترميز الأحرف للعنوان', 'Stelt de tekencodering van de URL in', 'Définit l''encodage des caractères de l''URL'),
  (23, 6, 3, FALSE, 'Identifies the client making the request', 'يحدد هوية العميل الذي يقوم بالطلب', 'Identificeert de client die de aanvraag stuurt', 'Identifie le client faisant la requête'),
  (25, 7, 1, TRUE, 'Hypermedia links in responses guide client navigation', 'روابط hypermedia في الاستجابات توجه تنقل العميل', 'Hypermedialinks in responses sturen clientnavigatie', 'Les liens hypermedia dans les réponses guident la navigation client'),
  (26, 7, 2, FALSE, 'A REST authentication standard', 'معيار مصادقة REST', 'Een REST-authenticatiestandaard', 'Un standard d''authentification REST'),
  (27, 7, 3, FALSE, 'An HTTP caching mechanism', 'آلية تخزين مؤقت HTTP', 'Een HTTP-cachemechanisme', 'Un mécanisme de mise en cache HTTP'),
  (29, 8, 1, TRUE, 'Too Many Requests – client exceeded the rate limit', 'طلبات كثيرة جداً — تجاوز العميل حد المعدل', 'Te Veel Verzoeken – client overschreed de snelheidslimiet', 'Trop de requêtes – le client a dépassé la limite de débit'),
  (30, 8, 2, FALSE, 'Unauthorized – credentials are missing or invalid', 'غير مصرح — بيانات الاعتماد مفقودة أو غير صحيحة', 'Ongeautoriseerd – inloggegevens ontbreken of zijn ongeldig', 'Non autorisé – identifiants manquants ou invalides'),
  (31, 8, 3, FALSE, 'Gateway Timeout – upstream server did not respond', 'انتهاء مهلة البوابة — الخادم الوسيط لم يستجب', 'Gateway Time-out – upstream-server reageerde niet', 'Délai de passerelle – le serveur en amont n''a pas répondu'),
  (33, 9, 1, TRUE, 'PATCH', 'PATCH', 'PATCH', 'PATCH'),
