  (37, 10, 1, TRUE, 'Structured Query Language', 'لغة الاستعلام الهيكلية', 'Structured Query Language', 'Structured Query Language'),
  (38, 10, 2, FALSE, 'Sequential Query Logic', 'منطق الاستعلام التسلسلي', 'Sequential Query Logic', 'Sequential Query Logic'),
  (39, 10, 3, FALSE, 'Standard Query Library', 'مكتبة الاستعلام القياسية', 'Standard Query Library', 'Bibliothèque de requêtes standard'),
  (41, 11, 1, TRUE, 'SELECT', 'SELECT', 'SELECT', 'SELECT'),
  (42, 11, 2, FALSE, 'GET', 'GET', 'GET', 'GET'),
  (43, 11, 3, FALSE, 'FETCH', 'FETCH', 'FETCH', 'FETCH'),
  (45, 12, 1, TRUE, 'A column or combination uniquely identifying each row', 'عمود أو مجموعة أعمدة تُعرّف كل صف بشكل فريد', 'Een kolom die elke rij uniek identificeert', 'Une colonne identifiant de manière unique chaque ligne'),
  (46, 12, 2, FALSE, 'The first indexed column in a table', 'أول عمود مفهرس في الجدول', 'De eerste geïndexeerde kolom in een tabel', 'La première colonne indexée d''une table'),
  (47, 12, 3, FALSE, 'A foreign key that references another table', 'مفتاح خارجي يشير إلى جدول آخر', 'Een vreemde sleutel die naar een andere tabel verwijst', 'Une clé étrangère référençant une autre table'),
  (49, 13, 1, TRUE, 'One query fetches parents, then one more query fires per child entity', 'استعلام واحد يجلب الآباء ثم استعلام إضافي لكل كيان ابن', 'Eén query haalt ouders op, daarna one extra query per kind-entiteit', 'Une requête charge les parents, puis une requête supplémentaire par entité enfant'),
  (50, 13, 2, FALSE, 'Executing N queries inside a single transaction', 'تنفيذ N استعلام داخل معاملة واحدة', 'N queries uitvoeren binnen een enkele transactie', 'Exécuter N requêtes dans une seule transaction'),
  (51, 13, 3, FALSE, 'An index fragmentation issue', 'مشكلة تجزؤ الفهرس', 'Een index-fragmentatieprobleem', 'Un problème de fragmentation d''index'),
  (53, 14, 1, TRUE, 'Only rows with matching values in both joined tables', 'فقط الصفوف ذات القيم المتطابقة في كلا الجدولين', 'Alleen rijen met overeenkomende waarden in beide tabellen', 'Uniquement les lignes avec des valeurs correspondantes dans les deux tables'),
  (54, 14, 2, FALSE, 'All rows from both tables regardless of match', 'كل الصفوف من كلا الجدولين بغض النظر عن التطابق', 'Alle rijen uit beide tabellen ongeacht overeenkomst', 'Toutes les lignes des deux tables quelle que soit la correspondance'),
  (55, 14, 3, FALSE, 'All rows from the left table and matched from right', 'كل صفوف الجدول الأيسر والمطابقة من الأيمن', 'Alle rijen uit de linker tabel en overeenkomende uit de rechter', 'Toutes les lignes de la table gauche et les correspondances à droite'),
  (57, 15, 1, TRUE, 'Speed up data retrieval operations', 'تسريع عمليات استرداد البيانات', 'Gegevensopvraging versnellen', 'Accélérer les opérations de récupération de données'),
  (58, 15, 2, FALSE, 'Enforce unique constraints on columns', 'فرض قيود التفرد على الأعمدة', 'Unieke beperkingen op kolommen afdwingen', 'Appliquer des contraintes d''unicité sur les colonnes'),
  (59, 15, 3, FALSE, 'Define foreign key relationships', 'تحديد علاقات المفتاح الخارجي', 'Relaties met vreemde sleutels definiëren', 'Définir les relations de clé étrangère'),
  (61, 16, 1, TRUE, 'Maintaining a pool of reusable connections to reduce overhead', 'الاحتفاظ بمجموعة من الاتصالات القابلة لإعادة الاستخدام', 'Een pool van herbruikbare verbindingen onderhouden om overhead te verminderen', 'Maintenir un pool de connexions réutilisables pour réduire la surcharge'),
  (62, 16, 2, FALSE, 'Encrypting all database connections', 'تشفير كل اتصالات قاعدة البيانات', 'Alle databaseverbindingen versleutelen', 'Chiffrer toutes les connexions à la base de données'),
  (63, 16, 3, FALSE, 'Distributing data across multiple databases', 'توزيع البيانات عبر قواعد بيانات متعددة', 'Gegevens verdelen over meerdere databases', 'Distribuer les données sur plusieurs bases de données'),
  (65, 17, 1, TRUE, 'Assuming no conflict and checking only at commit time', 'افتراض غياب التعارض والتحقق فقط عند الإيداع', 'Geen conflict aannemen en pas bij commit controleren', 'Supposer qu''il n''y a pas de conflit et vérifier seulement au commit'),
  (66, 17, 2, FALSE, 'Locking all rows at the start of every transaction', 'قفل كل الصفوف في بداية كل معاملة', 'Alle rijen vergrendelen aan het begin van elke transactie', 'Verrouiller toutes les lignes au début de chaque transaction'),
  (67, 17, 3, FALSE, 'Preventing concurrent read operations', 'منع عمليات القراءة المتزامنة', 'Gelijktijdige leesbewerkingen voorkomen', 'Empêcher les opérations de lecture simultanées'),
  (69, 18, 1, TRUE, 'A distributed system cannot simultaneously guarantee Consistency, Availability, and Partition tolerance', 'نظام موزع لا يمكنه ضمان الاتساق والتوافر وتسامح الانقسام في آنٍ واحد', 'Een gedistribueerd systeem kan niet tegelijkertijd Consistentie, Beschikbaarheid en Partitietolerantie garanderen', 'Un système distribué ne peut pas garantir simultanément Cohérence, Disponibilité et Tolérance aux partitions'),
  (70, 18, 2, FALSE, 'A database can achieve Consistency, Availability, and Performance simultaneously', 'يمكن لقاعدة البيانات تحقيق الاتساق والتوافر والأداء في آنٍ واحد', 'Een database kan Consistentie, Beschikbaarheid en Prestaties tegelijkertijd bereiken', 'Une base de données peut atteindre Cohérence, Disponibilité et Performance simultanément'),
  (71, 18, 3, FALSE, 'Caching, Availability, and Partitioning always coexist', 'التخزين المؤقت والتوافر والتقسيم يمكن دائماً التعايش معاً', 'Caching, Beschikbaarheid en Partitionering kunnen altijd samen bestaan', 'La mise en cache, la disponibilité et la partition coexistent toujours'),
  (73, 19, 1, TRUE, 'JSON Web Token', 'رمز الويب JSON', 'JSON Web Token', 'JSON Web Token'),
  (74, 19, 2, FALSE, 'JavaScript Widget Transfer', 'نقل عنصر JavaScript', 'JavaScript Widget Transfer', 'JavaScript Widget Transfer'),
  (75, 19, 3, FALSE, 'Java Web Transaction', 'معاملة ويب Java', 'Java Web Transaction', 'Java Web Transaction'),
  (77, 20, 1, TRUE, 'Header, Payload, Signature', 'الرأس، الحمولة، التوقيع', 'Header, Payload, Handtekening', 'En-tête, Charge utile, Signature'),
  (78, 20, 2, FALSE, 'Key, Value, Checksum', 'المفتاح، القيمة، مجموع التحقق', 'Sleutel, Waarde, Checksum', 'Clé, Valeur, Somme de contrôle'),
  (79, 20, 3, FALSE, 'Request, Response, Status', 'الطلب، الاستجابة، الحالة', 'Verzoek, Antwoord, Status', 'Requête, Réponse, Statut'),
  (81, 21, 1, TRUE, 'To prevent passwords being recovered if the database is compromised', 'لمنع استرداد كلمات المرور في حالة اختراق قاعدة البيانات', 'Om te voorkomen dat wachtwoorden worden achterhaald als de database is gehackt', 'Pour empêcher la récupération des mots de passe si la base de données est compromise'),
  (82, 21, 2, FALSE, 'To compress password storage space', 'لضغط مساحة تخزين كلمات المرور', 'Om de opslagruimte van wachtwoorden te comprimeren', 'Pour compresser l''espace de stockage des mots de passe'),
  (83, 21, 3, FALSE, 'To encrypt passwords during network transit', 'لتشفير كلمات المرور أثناء النقل عبر الشبكة', 'Om wachtwoorden te versleutelen tijdens netwerkoverdracht', 'Pour chiffrer les mots de passe pendant le transit réseau'),
  (85, 22, 1, TRUE, 'Authentication verifies who you are; Authorization determines what you can do', 'المصادقة تتحقق من هويتك؛ التفويض يحدد ما يمكنك فعله', 'Authenticatie verifieert wie u bent; Autorisatie bepaalt wat u mag doen', 'L''authentification vérifie qui vous êtes ; l''autorisation détermine ce que vous pouvez faire'),
  (86, 22, 2, FALSE, 'Authentication grants permissions; Authorization verifies identity', 'المصادقة تمنح الصلاحيات؛ التفويض يتحقق من الهوية', 'Authenticatie verleent rechten; Autorisatie verifieert identiteit', 'L''authentification accorde des droits ; l''autorisation vérifie l''identité'),
  (87, 22, 3, FALSE, 'They are two terms for the same process', 'هما مصطلحان لنفس العملية', 'Ze zijn twee termen voor hetzelfde proces', 'Ce sont deux termes pour le même processus'),
  (89, 23, 1, TRUE, 'Delegated access authorization without sharing credentials', 'تفويض الوصول المفوّض دون مشاركة بيانات الاعتماد', 'Gedelegeerde toegangsmachtiging zonder inloggegevens te delen', 'Autorisation d''accès délégué sans partager les identifiants'),
  (90, 23, 2, FALSE, 'Encrypting user passwords during transmission', 'تشفير كلمات مرور المستخدمين أثناء الإرسال', 'Gebruikerswachtwoorden versleutelen tijdens verzending', 'Chiffrer les mots de passe des utilisateurs lors de la transmission'),
  (91, 23, 3, FALSE, 'Securing database access permissions', 'تأمين أذونات الوصول إلى قاعدة البيانات', 'Databasetoegangsmachtigingen beveiligen', 'Sécuriser les autorisations d''accès à la base de données'),
  (93, 24, 1, TRUE, 'A long-lived credential used to obtain new access tokens', 'بيانات اعتماد طويلة الأمد تُستخدم للحصول على رموز وصول جديدة', 'Een langlevende credential om nieuwe toegangstokens te verkrijgen', 'Un justificatif de longue durée pour obtenir de nouveaux jetons d''accès'),
  (94, 24, 2, FALSE, 'A short-lived session identifier', 'معرّف جلسة قصير الأمد', 'Een kortlevende sessie-identifier', 'Un identifiant de session de courte durée'),
  (95, 24, 3, FALSE, 'A one-time verification code sent by email', 'رمز تحقق لمرة واحدة يُرسل عبر البريد الإلكتروني', 'Een eenmalige verificatiecode die per e-mail wordt verzonden', 'Un code de vérification à usage unique envoyé par e-mail'),
  (97, 25, 1, TRUE, 'Protection against authorization code interception attacks', 'الحماية من هجمات اعتراض رمز التفويض', 'Bescherming tegen het onderscheppen van autorisatiecodes', 'Protection contre les attaques d''interception du code d''autorisation'),
  (98, 25, 2, FALSE, 'A public-key certificate exchange mechanism', 'آلية تبادل شهادات المفتاح العام', 'Een uitwisselingsmechanisme voor publieke-sleutelcertificaten', 'Un mécanisme d''échange de certificats de clé publique'),
  (99, 25, 3, FALSE, 'A password-based key derivation function', 'دالة اشتقاق المفاتيح المستندة إلى كلمة المرور', 'Een wachtwoordgebaseerde sleutelafleiddingsfunctie', 'Une fonction de dérivation de clé basée sur un mot de passe'),
  (101, 26, 1, TRUE, 'Prevent replay attacks by binding the token to a specific request', 'منع هجمات إعادة التشغيل بربط الرمز بطلب محدد', 'Replay-aanvallen voorkomen door het token aan een specifiek verzoek te koppelen', 'Prévenir les attaques par relecture en liant le jeton à une requête spécifique'),
  (102, 26, 2, FALSE, 'Generate unique session identifiers', 'توليد معرّفات جلسة فريدة', 'Unieke sessie-identifiers genereren', 'Générer des identifiants de session uniques'),
  (103, 26, 3, FALSE, 'Encrypt the ID token payload', 'تشفير حمولة رمز الهوية', 'De payload van het ID-token versleutelen', 'Chiffrer la charge utile du jeton d''identité'),
  (105, 27, 1, TRUE, 'Requires two or more independent verification factors from different categories', 'يتطلب عاملَي تحقق مستقلّين أو أكثر من فئات مختلفة', 'Vereist twee of meer onafhankelijke verificatiefactoren uit verschillende categorieën', 'Nécessite deux facteurs de vérification indépendants ou plus de catégories différentes'),
  (106, 27, 2, FALSE, 'Requires users to change their password multiple times', 'يتطلب من المستخدمين تغيير كلمات المرور عدة مرات', 'Vereist dat gebruikers hun wachtwoord meerdere keren wijzigen', 'Exige que les utilisateurs changent leur mot de passe plusieurs fois'),
  (107, 27, 3, FALSE, 'Uses multiple devices simultaneously', 'يستخدم أجهزة متعددة في آنٍ واحد', 'Gebruikt meerdere apparaten tegelijkertijd', 'Utilise plusieurs appareils simultanément'),
