-- Flyway remains the owner of developer-exam reference content.
-- Exported from the final effective MySQL state; road-sign content is not duplicated here.






SELECT setval(pg_get_serial_sequence('dev_exam_categories', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM dev_exam_categories;
SELECT setval(pg_get_serial_sequence('dev_exam_category_i18n', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM dev_exam_category_i18n;
SELECT setval(pg_get_serial_sequence('dev_exam_questions', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM dev_exam_questions;
SELECT setval(pg_get_serial_sequence('dev_exam_choices', 'id'), COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM dev_exam_choices;
